package sep28;

public class qstn1_ASCIIVal {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		char alpha ='A';
		int num =alpha;
		System.out.println("ASCII Value of A is : "+num);
		
		char alpha1 ='a';
		int num1 =alpha1;
		System.out.println("ASCII Value of a is : "+num1);
		
		char alpha2 ='0';
		int num2 =alpha2;
		System.out.println("ASCII Value of 0 is : "+num2);
		
		char alpha3 ='@';
		int num3 =alpha3;
		System.out.println("ASCII Value of @ is : "+num3);
		
		

	}

}
